            }
        } else {
            count++;
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // Build adjacency list from paths
    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();
    for (int[] row : paths) {
        if (row.length != 2 * n) continue; // skip malformed rows
        int[] a = java.util.Arrays.copyOfRange(row, 0, n);
        int[] b = java.util.Arrays.copyOfRange(row, n, 2 * n);
        String keyA = coordKey.apply(a);
        String keyB = coordKey.apply(b);
        adjacency.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adjacency.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // If start and end are the same point
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // If start node has no connections, cannot travel
    if (!adjacency.containsKey(startKey)) {
        return "cannot be travelled";
    }

    // Breadth-first search to find a path
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String neighbor : adjacency.getOrDefault(current, java.util.Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

