public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        count[rem]++;
    }
    // Remainder 0 must be even
    if (count[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r < k; r++) {
        if (r > k - r) {
            continue; // already checked this pair
        }
        if (r == k - r) { // only when k is even and r == k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[k - r]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new java.util.ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    boolean[] visited = new boolean[n];
    int[] time = new int[1];
    dfs(0, graph, visited, hasApple, time);
    return time[0];
}

private boolean dfs(int node, java.util.List<Integer>[] graph, boolean[] visited, boolean[] hasApple, int[] time) {
    visited[node] = true;
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (!visited[nei]) {
            boolean childHas = dfs(nei, graph, visited, hasApple, time);
            if (childHas) {
                time[0] += 2;
                has = true;
            }
        }
    }
    return has;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (char ch : s.toCharArray()) {
        freq[ch - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                // After ascending, start descending from the largest possible
                // but we need to remember the last appended index
                int lastIndex = i;
                // Descending pass
                for (int j = 25; j > lastIndex; j--) {
                    if (freq[j] > 0) {
                        result.append((char) ('a' + j));
                        freq[j]--;
                    }
                }
                // After descending, continue with next ascending pass
                // but we need to skip the characters already processed
                // So we break to outer while loop
                break;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n / 2 + 1];
    for (int i = 0; i <= n / 2; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = Math.min(n / 2, n); k >= 1; k--) {
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

