public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
                // balance stays 0
            }
        }
    }
    insertions += balance;
    return insertions;
}

