public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        maxEnding = Math.max(num, maxEnding + num);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(num, minEnding + num);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(maxSoFar, Math.abs(minSoFar));
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // sufficient size for k up to 10^9
    int size = 0;
    fib[size++] = 1;
    fib[size++] = 1;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) break;
        fib[size++] = next;
    }

    // Greedy subtraction from the largest Fibonacci number
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

