public String getSmallestString(int n, int k) {
    char[] arr = new char[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 'a';
    }
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        arr[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(arr);
}

