public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiagonal[i][j] = (i > 0 && j < n - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;

                int currentMax = Math.max(
                        Math.max(horizontal[i][j], vertical[i][j]),
                        Math.max(diagonal[i][j], antiDiagonal[i][j])
                );
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j] = 0;
                diagonal[i][j] = 0;
                antiDiagonal[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    boolean negative = n < 0;
    long num = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        count++;
        if (num > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    boolean[] visited = new boolean[n];
    return backtrack(A, visited, -1, 0);
}

private static int backtrack(int[] A, boolean[] visited, int prev, int depth) {
    int n = A.length;
    if (depth == n) return 1;
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
        if (prev == -1 || isSquare(A[i] + prev)) {
            visited[i] = true;
            count += backtrack(A, visited, A[i], depth + 1);
            visited[i] = false;
        }
    }
    return count;
}

private static boolean isSquare(int x) {
